import React, { useState, useEffect } from "react";
import PostThumb from "../PostThumb";
import LoadIcon from "../../images/loading.gif";
import LoadMoreBtn from "../LoadMoreBtn";
import { getDataAPI, getErrorMessage } from "../../utils/fetchData";
import { GLOBALTYPES } from "../../redux/actions/globalTypes";

const Saved = ({ auth, dispatch }) => {
  const [savePosts, setSavePosts] = useState([]);
  const [result, setResult] = useState(9);
  const [page, setPage] = useState(2);
  const [load, setLoad] = useState(false);

  useEffect(() => {
    setLoad(true);
    getDataAPI(`getSavePosts`, auth.token)
    .then(res => { 
        setSavePosts(res.data.savePosts) 
        setResult(res.data.result)
        setLoad(false)
    })  
    .catch(err => {
        dispatch({type: GLOBALTYPES.ALERT, payload: {error: getErrorMessage(err)}})
        setLoad(false)
    })

    return () => setSavePosts([]);
  }, [dispatch, auth.token]);

  const handleLoadMore = async () => {
    setLoad(true);
    const res = await getDataAPI(`getSavePosts?limit=${page * 9}`, auth.token);
    setSavePosts(res.data.savePosts);
    setResult(res.data.result);
    setPage(page + 1);
    setLoad(false);
  };


  return (
    <div>
      <PostThumb
        posts={savePosts}
        result={result}
        emptyIcon="bookmark_border"
        emptyTitle="Save posts"
        emptyText="Save photos and videos that you want to see again."
      />

      {load && (
        <img src={LoadIcon} alt="Loading..." className="mx-auto my-6 h-14 w-14" />
      )}

      <LoadMoreBtn
        result={result}
        page={page}
        load={load}
        handleLoadMore={handleLoadMore}
      />
    </div>
  );
};

export default Saved;
